SELECT ?pt ?class WHERE { 
  ?z a brick:HVAC_Zone . 
  ?z brick:hasPoint ?pt . 
  ?pt rdf:type brick:Zone_Air_Temperature_Sensor .
} LIMIT 200

SELECT ?pt ?class ?ref ?tsid WHERE { 
  ?z a brick:HVAC_Zone . 
  ?z brick:hasPoint ?pt .
  ?pt rdf:type ?class .
  OPTIONAL { ?pt ref:hasExternalReference ?ref }
  OPTIONAL { ?pt ref:hasTimeseriesId ?tsid }
} LIMIT 200

SELECT ?pt ?class ?ref ?tsid WHERE { 
  ?z a brick:HVAC_Zone . 
  FILTER(str(?z) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z01")
  ?z brick:hasPoint ?pt .
  ?pt rdf:type ?class .
  OPTIONAL { ?pt ref:hasExternalReference ?ref }
  OPTIONAL { ?pt ref:hasTimeseriesId ?tsid }
} LIMIT 50

